// org.site.create — E1 AC1, AC2: a project/site gets the Project ID CLIENT-CC-CITY-NNN with a running number
// per client and city (SOP-DEL-02 §3, D-18). Generated by `pnpm gen:command`; guard cases kept.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import { aStaffActor, countRows, createTestDatabase, runAsOwner, type TestDatabase } from '@ocs/testing';
import {
  Forbidden,
  NotFound,
  openTestKernel,
  ValidationFailed,
  type TestKernel,
} from '../../kernel/index.ts';
import { createClient } from '../commands/create-client.ts';
import { createSite } from '../commands/create-site.ts';

const director = aStaffActor({ roles: ['director'] });
const other = aStaffActor();
let testDb: TestDatabase;
let t: TestKernel;
let clientA: string;
let clientB: string;

const madrid = { countryCode: 'es', cityCode: 'mad', cityName: 'Madrid', standard: 'L' } as const;
const create = (clientId: string, name: string, place: Partial<Record<keyof typeof madrid, string>> = {}) =>
  t.kernel.execute(createSite, director, { clientId, name, ...madrid, ...place }, 'test');

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  t = await openTestKernel(testDb.url);
  t.grant(director, createClient.permission, createSite.permission);
  clientA = (
    await t.kernel.execute(createClient, director, { shortCode: 'CLIENTA', name: 'Client A' }, 'test')
  ).id;
  clientB = (
    await t.kernel.execute(createClient, director, { shortCode: 'CLIENTB', name: 'Client B' }, 'test')
  ).id;
});

afterAll(async () => {
  await t.close();
  await testDb.drop();
});

describe('org.site.create', () => {
  it('refuses an actor without the permission and records nothing', async () => {
    const attempt = t.kernel.execute(
      createSite,
      other,
      { clientId: clientA, name: 'Site 001', ...madrid },
      'test',
    );
    await expect(attempt).rejects.toBeInstanceOf(Forbidden);
    expect(await countRows(testDb.url, 'site')).toBe(0);
  });

  it('refuses a standard other than L or S', async () => {
    await expect(create(clientA, 'Site 001', { standard: 'M' })).rejects.toBeInstanceOf(ValidationFailed);
  });

  it('numbers sites per client and city: CLIENTA-ES-MAD-001, -002; another city or client starts at 001', async () => {
    expect((await create(clientA, 'Site 001')).projectId).toBe('CLIENTA-ES-MAD-001');
    expect((await create(clientA, 'Site 002')).projectId).toBe('CLIENTA-ES-MAD-002');
    expect(
      (
        await create(clientA, 'Site 003', {
          countryCode: 'PT',
          cityCode: 'LIS',
          cityName: 'Lisbon',
          standard: 'S',
        })
      ).projectId,
    ).toBe('CLIENTA-PT-LIS-001');
    expect((await create(clientB, 'Site 004')).projectId).toBe('CLIENTB-ES-MAD-001');
    expect(await countRows(testDb.url, `audit_event WHERE command = 'org.site.create'`)).toBe(4);
    expect(await countRows(testDb.url, `outbox WHERE event_type = 'org.site.created'`)).toBe(4);
  });

  it('two sites created at the same moment still get different running numbers', async () => {
    const [x, y] = await Promise.all([create(clientB, 'Site 005'), create(clientB, 'Site 006')]);
    expect([x.projectId, y.projectId].sort()).toEqual(['CLIENTB-ES-MAD-002', 'CLIENTB-ES-MAD-003']);
  });

  it('never reuses a running number, also after a site is archived', async () => {
    await runAsOwner(
      testDb.url,
      `UPDATE site SET archived_at = now() WHERE project_id = 'CLIENTA-ES-MAD-002'`,
    );
    expect((await create(clientA, 'Site 007')).projectId).toBe('CLIENTA-ES-MAD-003');
  });

  it('refuses a malformed city code, citing SOP-DEL-02 §3', async () => {
    await expect(create(clientA, 'Site 008', { cityCode: 'MADR' })).rejects.toMatchObject({
      clause: 'SOP-DEL-02 §3',
    });
  });

  it('refuses an unknown or archived client', async () => {
    await expect(create(randomUUID(), 'Site 009')).rejects.toBeInstanceOf(NotFound);
    await runAsOwner(testDb.url, 'UPDATE client SET archived_at = now() WHERE id = $1', [clientB]);
    await expect(create(clientB, 'Site 010')).rejects.toBeInstanceOf(NotFound);
  });
});
